"use client";
// Client entry points for the contracts actions (generated by scripts/gen-actions.py).
// Each call POSTs to /api/actions/contracts/<name>; implementations live in src/server/actions-impl/contracts.ts.
import { remoteAction } from "@/lib/remote-action";

export const createContractAction = remoteAction("contracts", "createContractAction");
export const updateContractAction = remoteAction("contracts", "updateContractAction");
export const submitContractAction = remoteAction("contracts", "submitContractAction");
export const approveContractAction = remoteAction("contracts", "approveContractAction");
export const rejectContractAction = remoteAction("contracts", "rejectContractAction");
export const terminateContractAction = remoteAction("contracts", "terminateContractAction");
